using System;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
public static class RetroDungeonExperimentInstaller {
 const string Folder="Assets/Resources/RetroDungeonExperiment";
 static T Asset<T>(string name) where T:ScriptableObject{string path=Folder+"/"+name+".asset";var asset=AssetDatabase.LoadAssetAtPath<T>(path);if(asset==null){asset=ScriptableObject.CreateInstance<T>();AssetDatabase.CreateAsset(asset,path);}return asset;}
 static Texture2D Texture(string name){return AssetDatabase.LoadAssetAtPath<Texture2D>(Folder+"/Layers/"+name+".png");}
 [MenuItem("Editor/Experimentos/Preparar dungeon retro luminoso")]
 public static string Install(){
  foreach(var path in AssetDatabase.FindAssets("t:Texture2D",new[]{Folder+"/Layers"})){var file=AssetDatabase.GUIDToAssetPath(path);var importer=AssetImporter.GetAtPath(file) as TextureImporter;if(importer==null)continue;importer.filterMode=FilterMode.Point;importer.npotScale=TextureImporterNPOTScale.None;importer.alphaIsTransparency=true;importer.wrapMode=file.EndsWith("Floor.png")?TextureWrapMode.Repeat:TextureWrapMode.Clamp;importer.textureCompression=TextureImporterCompression.Uncompressed;importer.SaveAndReimport();}
  var settings=Asset<RetroDungeonSettings>("Settings");settings.sky=Texture("Sky");settings.floor=Texture("Floor");settings.pipe=Texture("Pipe");settings.clouds=new[]{Texture("Clouds-8"),Texture("Clouds-5"),Texture("Clouds-7")};settings.mountains=new[]{Texture("Mountains-4"),Texture("Mountains-2")};settings.bushes=new[]{Texture("Bushes-10"),Texture("Bushes-11"),Texture("Bushes-3")};settings.interactiveCell=new Vector2Int(17,14);settings.pipeWallDirection=1;
  var map=Asset<DungeonMapSettings>("Map");map.mapId="experiment.retro.luminous.v1";map.includeLegacyObjects=false;map.digitalDoorsEnabled=true;map.startCell=new Vector2Int(5,1);map.startHeading=0;map.entities=Asset<DungeonEntitySettings>("Objects");map.regions=Asset<DungeonRegionSettings>("Regions");map.regions.legacyPlacements=false;map.regions.initialRandomPerZone=0;
  const int width=21,height=20;var grid=new char[height][];for(int y=0;y<height;y++){grid[y]=new char[width];for(int x=0;x<width;x++)grid[y][x]='#';}
  for(int y=1;y<=6;y++)grid[y][5]='.';for(int y=6;y<=12;y++)for(int x=2;x<=8;x++)grid[y][x]='.';for(int x=8;x<=10;x++)grid[9][x]='.';for(int y=9;y<=13;y++)grid[y][10]='.';for(int y=10;y<=16;y++)for(int x=11;x<=17;x++)grid[y][x]='.';
  map.rows=Array.ConvertAll(grid,row=>new string(row));var zone=Asset<EnemyZoneSettings>("Enemies");EditorUtility.CopySerialized(EnemyZoneSettings.Current,zone);zone.zoneId="retro.experiment";zone.minimumLevel=zone.maximumLevel=1;zone.maximumEnemies=3;zone.species=new[]{new SpeciesSpawnWeight{speciesId="Hongo",weight=1}};
  var region=new DungeonRegion{id="retro.experiment",displayName="Prueba retro luminosa",enemies=zone};for(int y=0;y<height;y++)for(int x=0;x<width;x++)if(grid[y][x]=='.')region.cells.Add(new Vector2Int(x,y));map.regions.regions=new[]{region};var placements=new List<PlacedEnemyDefinition>();foreach(var id in settings.placementIds)placements.Add(new PlacedEnemyDefinition{id=id,speciesId="Hongo",cell=settings.interactiveCell,trigger=EncounterTrigger.InteractiveEvent,unique=true,respawn=false,holdPosition=true,randomLevel=false,fixedLevel=1,exploration=new EnemyExplorationSettings{profile=EnemyExplorationProfile.Static,persistence=EnemyExplorationPersistence.PermanentDefeat}});map.regions.placedEnemies=placements.ToArray();
  map.entities.objects=new List<DungeonMapEntity>{new DungeonMapEntity{id="retro.sections.door",displayName="Puerta de prueba",kind=DungeonEntityKind.Door,cell=new Vector2Int(10,11),heading=0}};
  var encounters=Asset<EnemyEncounterSettings>("Encounters");EditorUtility.CopySerialized(Resources.Load<EnemyEncounterSettings>("Exploration/EnemyEncounterSettings"),encounters);encounters.minimumSpawnNavigationSteps=2;encounters.minimumMapSpacing=2;encounters.spawnOutsideView=false;encounters.safeAreaBufferSteps=encounters.doorwayBufferSteps=0;encounters.directorCheckEverySteps=100000;encounters.longQuietWalkSteps=100000;
  foreach(var obj in new UnityEngine.Object[]{settings,map,map.entities,map.regions,zone,encounters})EditorUtility.SetDirty(obj);AssetDatabase.SaveAssets();
  const string scenePath="Assets/Scenes/RetroDungeonExperiment.unity";if(!System.IO.File.Exists(scenePath)){var old=SceneManager.GetActiveScene();var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Additive);SceneManager.SetActiveScene(scene);var root=new GameObject("Retro dungeon experiment");var dungeon=root.AddComponent<DungeonPrototype>();dungeon.mapSettings=map;dungeon.dungeonRegions=map.regions;dungeon.enemyEncounterSettings=encounters;var composer=root.AddComponent<RetroDungeonWallComposer>();composer.dungeon=dungeon;composer.settings=settings;EditorSceneManager.SaveScene(scene,scenePath);EditorSceneManager.CloseScene(scene,true);SceneManager.SetActiveScene(old);}
  return scenePath+" (not added to release build)";
 }
}
